import json,copy,itertools,hashlib
from pathlib import Path
import numpy as np
import toolbar_back_surface_sextic as m
out=Path('/tmp/agent-toolbar-back-sextic');out.mkdir(exist_ok=True);report={'completed_groups':[],'new_target_image_fits':0}
def save(name,data):
    report['completed_groups'].append(name);report[name]=data;(out/'invariants-in-progress.json').write_text(json.dumps(report,indent=2)+'\n');print('CHECK',name,data,flush=True)
p=json.loads(Path('/tmp/agent-toolbar-back-surface/recipe.json').read_text());p['back_surface']['sextic']=.015;x,y=np.meshgrid(np.linspace(-2.3,2.3,83),np.linspace(-1,1,39));inside=m.parent.implicit(x,y,p)[0]<.995;x=x[inside];y=y[inside]
zero=copy.deepcopy(p);zero['back_surface']['sextic']=0.;z=m.mapping(x,y,zero);old=m.parent.mapping(x,y,zero);assert all(np.array_equal(a,b) for a,b in zip(z,old));save('zero_parent_exact',True)
eps=1e-5;T,h,hx,hy=m.surface_field(x,y,p);xf=(m.surface_field(x+eps,y,p)[1]-m.surface_field(x-eps,y,p)[1])/(2*eps);yf=(m.surface_field(x,y+eps,p)[1]-m.surface_field(x,y-eps,p)[1])/(2*eps);e=max(float(np.max(np.abs(hx-xf))),float(np.max(np.abs(hy-yf))));assert e<1e-8;save('complete_gradient_max_error',e)
X,Y,valid,aux=m.rays(x,y,p);assert np.all(valid);q=p['back_surface'];G=q['background'];V=np.stack([X-x,Y-y,-(G-h)],axis=-1);V/=np.linalg.norm(V,axis=-1)[...,None];normal=np.stack([-hx,-hy,-np.ones_like(h)],axis=-1);normal/=np.linalg.norm(normal,axis=-1)[...,None];I=np.zeros_like(V);I[...,2]=-1;e=float(np.max(np.abs(np.cross(q['ior']*I-V,normal))));assert e<1e-12 and np.all(np.sum(V*normal,axis=-1)>0);save('Snell_normal_alignment_max_error',e)
mx,my=m.mapping(-x,y,p);mir=max(float(np.max(np.abs(mx+X))),float(np.max(np.abs(my-Y))));rot=copy.deepcopy(p);rot['shape']['half']=list(reversed(p['shape']['half']));rx,ry=m.mapping(-y,x,rot);ro=max(float(np.max(np.abs(rx+Y))),float(np.max(np.abs(ry-X))));scale=copy.deepcopy(p);scale['shape']['half']=[2*v for v in p['shape']['half']];scale['shape']['radius']*=2;sx,sy=m.mapping(2*x,2*y,scale);sc=max(float(np.max(np.abs(sx-2*X))),float(np.max(np.abs(sy-2*Y))));assert max(mir,ro,sc)<1e-12;save('mirror_rotation_scale_errors',[mir,ro,sc])
circle=copy.deepcopy(p);circle['shape']={'half':[1.,1.],'radius':1.};circle['footprint_softness']=0.;circle['back_surface'].update(b_major=-.01,b_minor=-.01,quartic=-.1);t=np.linspace(0,2*np.pi,131);xx=.7*np.cos(t);yy=.7*np.sin(t);cx,cy=m.mapping(xx,yy,circle);angle=.37;crx,cry=m.mapping(np.cos(angle)*xx-np.sin(angle)*yy,np.sin(angle)*xx+np.cos(angle)*yy,circle);ce=max(float(np.max(np.abs(crx-(np.cos(angle)*cx-np.sin(angle)*cy)))),float(np.max(np.abs(cry-(np.sin(angle)*cx+np.cos(angle)*cy)))));assert ce<1e-12;save('true_circle_nonzero_sextic_rotation_error',ce)
corners=[]
for bm,bn,c,l in itertools.product([-.03,.03],[-.03,.03],[-.15,.15],[-.02,.02]):
    cp=copy.deepcopy(p);cp['back_surface'].update(b_major=bm,b_minor=bn,quartic=c,sextic=l);bound=m.analytic_bounds(cp);assert bound['global_subcritical_positive_clearance'] and bound['no_reentry_sufficient_product']<1;_,height,gx,gy=m.surface_field(x,y,cp);_,_,v,aux=m.rays(x,y,cp);assert np.all(v) and height.min()>=bound['height_lower']-1e-12 and height.max()<=bound['height_upper']+1e-12 and np.hypot(gx,gy).max()<=bound['gradient_norm_upper']+1e-12
    bound['parameters']=[bm,bn,c,l];corners.append(bound)
disp=max(b['displacement_norm_upper'] for b in corners)*170;case=p['case'];image_margins=[case['center'][0]-case['half'][0]-disp,1920-1-(case['center'][0]+case['half'][0]+disp),case['center'][1]-case['half'][1]-disp,1080-1-(case['center'][1]+case['half'][1]+disp)];assert min(image_margins)>1;save('box16_global_bounds',{'corners':corners,'full_source_native_margin_lower_px':image_margins})
